import {createProject,createCharacter,normalizeProject,clone,PARTS,PART_IDS,PALETTES,escapeXml as e,applyDesign,designChanges,applySelectedChanges,physicalScale,uid,pose,transforms,partBounds} from './model.mjs?v=0.10.0';
import {fullSvg,puppet,partPreview,printPages,inspection,accessoryArt,propPrintPages} from './render.mjs?v=0.10.0';
import {askAssistant,generateStudioImage,RELAY} from './agent.mjs?v=0.10.0';
const $=s=>document.querySelector(s),root=$('#app'),storageKey='bnta-shadow-studio-v1';
let project=createProject(),step='shape',selectedPart=null,view='color',showJoints=true,selectedAccessory=null,playing=false,motion='wave',frame=0,chat=[],proposal=null,proposalBase='',proposalTarget=null,busy=false,controller=null,imageBusy=false,imageController=null,endpoint=RELAY,undoStack=[],redoStack=[],toastTimer,dirty=false,connectionState='unverified',sketching=false,aiOpen=false,versionsOpen=false,showParts=false,changeSelection=[],castSelection=[];
// Projects stay in this open session. Remove only the former classic autosave.
try{localStorage.removeItem(storageKey);}catch{}
const t=(en,zh)=>project.language==='zh'?zh:en,character=()=>project.characters[project.selected];
const icons={story:'M4 3h13v16H4z M7 7h7 M7 11h7 M7 15h4',characters:'M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-2a8 6 0 0 1 16 0v2',design:'m4 17-1 4 4-1L20 7l-3-3z M14 7l3 3',motion:'m9 4 10 8-10 8z',make:'M5 3h14v5H5z M5 16H3V8h18v8h-2 M5 13h14v8H5z',history:'M3 10a9 9 0 1 1 2 8 M3 4v6h6 M12 7v6l4 2',save:'M4 3h14l3 3v15H3V3z M7 3v6h9V3 M7 21v-8h10v8',upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v6h16v-6',undo:'M9 5 3 11l6 6 M3 11h11a6 6 0 0 1 6 6',redo:'m15 5 6 6-6 6 M21 11H10a6 6 0 0 0-6 6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',arrow:'M4 12h16 m-6-6 6 6-6 6',plus:'M12 4v16 M4 12h16',close:'m5 5 14 14 M19 5 5 19',play:'m8 4 12 8-12 8z',pause:'M8 4v16 M16 4v16',download:'M12 3v13 m-5-5 5 5 5-5 M4 18v3h16v-3',check:'m4 12 5 5L20 6'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.spark}"/></svg>`;
const btn=(action,label,cls='',extra='')=>`<button data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
const opts=(values,current)=>values.map(([v,label])=>`<option value="${v}" ${v===current?'selected':''}>${label}</option>`).join('');
function field(label,key,value,{kind='input',options,rows=3}={}){return `<label class="field"><span>${label}</span>${kind==='textarea'?`<textarea data-field="${key}" rows="${rows}">${e(value)}</textarea>`:kind==='select'?`<select data-field="${key}">${opts(options,value)}</select>`:`<input data-field="${key}" value="${e(value)}" maxlength="${key==='name'?100:1000}">`}</label>`;}

const displayName=c=>c.name||t('Unnamed puppet','未命名皮影');
const steps=[['shape','Shape','塑形'],['style','Style','装扮'],['motion','Test','测试'],['make','Make','制作']];
function scopeLabel(){return selectedPart?t(PARTS.find(p=>p.id===selectedPart).en,PARTS.find(p=>p.id===selectedPart).zh):t('Whole puppet','整个皮影');}
function sizeControl(){return '<label class="field"><span>'+t('Finished print height (mm)','成品打印高度（毫米）')+'</span><input type="number" data-number="height" min="180" max="350" value="'+project.height+'"></label><p class="hint">'+t('Changes print size. Body proportions are edited separately.','此项改变打印尺寸。身体比例可单独调整。')+'</p>';}
function choices(key,label,items,current){return '<fieldset class="choice-field"><legend>'+label+'</legend><div class="choice-grid">'+items.map(([value,en,zh])=>{const sample=clone(character());sample[key]=value;const visual=['hair','clothing','pattern','faceShape'].includes(key)?partPreview(sample,['hair','faceShape'].includes(key)?'head':'torso').replaceAll('tabindex="0"','tabindex="-1"').replaceAll('clip-detail-','clip-choice-'+key+'-'+value+'-'):'';return '<button type="button" data-choice="'+key+'" data-value="'+value+'" aria-pressed="'+(value===current)+'" class="'+(value===current?'active':'')+'">'+(visual?'<span class="choice-sample" aria-hidden="true">'+visual+'</span>':'')+t(en,zh)+'</button>';}).join('')+'</div></fieldset>';}

function lockControls(){return '<details class="lock-controls"><summary>'+t('Protect features from AI','锁定 AI 不可修改的特征')+'</summary>'+[['face','Face & hair','面部与发型'],['body','Body proportions & joints','身体比例与关节'],['costume','Costume & colors','服装与颜色'],['props','Props','道具']].map(([key,en,zh])=>'<label class="checkbox"><input type="checkbox" data-feature-lock="'+key+'" '+(character().locks[key]?'checked':'')+'>'+t(en,zh)+'</label>').join('')+'</details>';}
function nextStep(){const i=steps.findIndex(x=>x[0]===step);return i<0?'':'<div class="journey-actions">'+(i?'<button data-step="'+steps[i-1][0]+'">← '+t(steps[i-1][1],steps[i-1][2])+'</button>':'<span></span>')+(i<3?'<button class="primary" data-step="'+steps[i+1][0]+'">'+t('Next: ','下一步：')+t(steps[i+1][1],steps[i+1][2])+' →</button>':'')+'</div>';}
function changeLabel(path){const labels={name:['Name (text)','名称（文字）'],role:['Role (text)','角色定位（文字）'],brief:['Brief (text)','简介（文字）'],action:['Required action (text)','所需动作（文字）'],age:['Age details','年龄特征'],gender:['Gender (description only)','性别（仅描述）'],hair:['Hair','发型'],clothing:['Costume','服装'],pattern:['Pattern','图案'],faceShape:['Face shape','脸型'],primary:['Costume color','服装颜色'],secondary:['Contrast color','对比色'],accent:['Detail color','装饰色'],skin:['Face color','肤色'],hairColor:['Hair color','发色'],accessories:['Props','道具'],'garment.sleeveWidth':['Sleeve width','袖子宽度'],'garment.sleeveLength':['Sleeve length','袖子长度'],'garment.hemLength':['Hem length','衣摆长度']};if(labels[path])return t(...labels[path]);const [_,id,key]=path.split('.');return t(PARTS.find(p=>p.id===id)?.en||id,PARTS.find(p=>p.id===id)?.zh||id)+' · '+t({width:'width',length:'length',angle:'angle'}[key]||key,{width:'宽度',length:'长度',angle:'角度'}[key]||key);}
function changeValue(value){return Array.isArray(value)?value.length+' '+t('props','个道具'):e(String(value??''));}

function toast(message){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}

function checkpoint(){undoStack.push(JSON.stringify(project));if(undoStack.length>40)undoStack.shift();redoStack=[];}
function sessionStatus(){return dirty?t('Session changes — download to keep','本次会话的修改，请下载保留'):t('Session only — download to keep','仅限本次会话，请下载保留');}
function downloadProject(){download('shadow-studio-project.json',JSON.stringify(project,null,2),'application/json');dirty=false;const el=$('#saved-state');if(el)el.textContent=sessionStatus();}
function changed(){dirty=true;const el=$('#saved-state');if(el)el.textContent=sessionStatus();}
function commit(fn){checkpoint();fn();changed();render();}
function pageHeader(){const names={shape:[t('Start with a simple shape.','从基础形态开始。'),t('A blank puppet, ready for your ideas. Select a part to change its proportions.','从空白皮影开始。选择部件，调整比例。')],style:[t('Make it your own.','设计你的皮影。'),t('Choose hair, costume, colors and props. Ask AI for help when you need it.','选择发型、服装、颜色和道具。需要时再请 AI 协助。')],motion:[t('Try it in motion.','让皮影动起来。'),t('Check your gesture, joints and overlaps before making a physical prototype.','检查动作、关节和重叠区域，再制作实体原型。')],make:[t('Ready for the light.','准备登台。'),t('Print at actual size, assemble, then test and revise.','按实际尺寸打印、组装、测试和修改。')],story:[t('Your project story.','你的项目故事。'),t('Optional. Write your own idea or paste a script. Nothing is filled in for you.','可选。写下自己的想法或粘贴剧本，从空白开始。')],characters:[t('Your puppets.','你的皮影。'),t('Add a plain template for each new character.','为每个新角色添加基础模板。')]};return '<div class="page-heading"><div><div class="eyebrow">'+t('YOUR SHADOW PUPPET WORKSHOP','你的皮影工作室')+'</div><h1>'+names[step][0]+'</h1><p>'+names[step][1]+'</p></div></div>';}
function render(){cancelAnimationFrame(frame);if(step!=='motion')playing=false;root.innerHTML=`<header class="topbar"><div class="brand"><span class="seal">影</span><div><strong>皮影 / Shadow Studio</strong><small>BNTA · ${t('Interdisciplinary Education','交叉学科教育')}</small></div></div><div class="top-actions"><span class="saved" id="saved-state">${sessionStatus()}</span>${btn('language',project.language==='en'?'中文':'English','small')}${btn('new-project',t('New project','新建项目'),'small')}${btn('import',t('Open','打开'),'small')}${btn('save',icon('save')+' '+t('Download project','下载项目'),'dark small')}</div></header><div class="shell"><nav class="sidebar" aria-label="${t('Design steps','设计步骤')}"><div class="eyebrow">${t('Make your puppet','制作皮影')}</div>${steps.map(([id,en,zh],i)=>`<button class="nav ${step===id?'active':''}" data-step="${id}" ${step===id?'aria-current="page"':''}><span class="step-no">${i+1}</span><span>${t(en,zh)}</span></button>`).join('')}<div class="nav-divider"></div>${[['story','Project story','项目故事'],['characters','My puppets','我的皮影']].map(([id,en,zh])=>`<button class="nav ${step===id?'active':''}" data-step="${id}" ${step===id?'aria-current="page"':''}>${icon(id)}<span>${t(en,zh)}</span></button>`).join('')}${btn('versions',icon('history')+' '+t('Versions','版本记录'),'nav')}<div class="sidebar-note"><p>${t('Shape an idea.<br>Test a movement.<br>Tell your story.','设计形态。<br>测试动作。<br>讲述故事。')}</p>${btn('about',t('About','关于'),'small ghost')}</div></nav><main class="main">${pageHeader()}${({shape:designPage,style:designPage,motion:motionPage,story:storyPage,characters:charactersPage,make:makePage})[step]()}${nextStep()}<footer class="footer"><span>BNTA · ${t('This session resets when reopened. Download a project to keep it.','再次打开时会重新开始，请下载项目以保留作品。')}</span><span>${t('Physical testing required','请进行实体测试')}</span></footer></main></div>${versionsOpen?`<div class="drawer-backdrop"><aside class="versions-drawer" role="dialog" aria-modal="true" aria-label="${t('Versions','版本记录')}" tabindex="-1"><div class="panel-head"><h2>${t('Versions','版本记录')}</h2>${btn('versions',t('Close','关闭'),'small')}</div>${historyPage()}</aside></div>`:''}`;if(playing)animate();bindStage();const log=$('.chat-log');if(log)log.scrollTop=log.scrollHeight;if(versionsOpen)$('.versions-drawer')?.focus();}
function characterPicker(){return '<label class="field"><span>'+t('Current puppet','当前皮影')+'</span><select id="character-select">'+project.characters.map((c,i)=>'<option value="'+i+'" '+(i===project.selected?'selected':'')+'>'+e(displayName(c))+'</option>').join('')+'</select></label>';}
function designControls(){const c=character();const shape=`${field(t('Name (optional)','名称（可选）'),'name',c.name)}${choices('age',t('Age details','年龄特征'),[['child','Child','儿童'],['teen','Teen','少年'],['adult','Adult','成人'],['elder','Elder','长者']],c.age)}${choices('faceShape',t('Face shape','脸型'),[['neutral','Neutral','基础'],['soft','Soft','圆润'],['angular','Angular','棱角']],c.faceShape)}<details><summary>${t('Character description (optional)','角色描述（可选）')}</summary>${field(t('Gender — description only','性别——仅作描述'),'gender',c.gender,{kind:'select',options:[['unspecified',t('Unspecified','不指定')],['female',t('Female','女性')],['male',t('Male','男性')]]})}<p class="hint">${t('Gender does not automatically choose a face, hair or costume. You choose those features.','性别不会自动决定脸型、发型或服装，这些特征由你选择。')}</p>${field(t('Story role','故事中的角色'),'role',c.role)}</details><div class="divider"></div><strong>${t('Body proportions','身体比例')}</strong><p class="hint">${t('Select the head, torso or a limb on the puppet to adjust width and length.','选择皮影的头部、躯干或四肢，调整宽度和长度。')}</p>${sizeControl()}`;
 const style=`${choices('hair',t('Hair / headwear','发型 / 头饰'),[['none','None','无'],['short','Short','短发'],['long','Long','长发'],['bun','Bun','发髻'],['cap','Cap','帽子']],c.hair)}${choices('clothing',t('Costume','服装'),[['base','Basic','基础'],['robe','Robe','长袍'],['tunic','Tunic','短衣'],['jacket','Jacket','夹克']],c.clothing)}<div class="garment-controls">${[['sleeveWidth','Sleeve width','袖子宽度',.8,1.6],['sleeveLength','Sleeve length','袖子长度',.65,1.3],['hemLength','Hem length','衣摆长度',.7,1.35]].map(([key,en,zh,min,max])=>`<label class="field"><span>${t(en,zh)} <output id="garment-${key}">${c.garment[key]}×</output></span><input type="range" data-garment="${key}" min="${min}" max="${max}" step=".01" value="${c.garment[key]}"></label>`).join('')}<p class="hint">${t('Clothing changes independently of arms, legs and joints.','服装可独立调整，不改变四肢和关节。')}</p></div>${choices('pattern',t('Pattern','图案'),[['plain','Plain','素色'],['cloud','Cloud','云纹'],['floral','Floral','花纹'],['geometric','Geometric','几何']],c.pattern)}<div class="color-row">${[['primary','Costume','服装'],['secondary','Contrast','对比'],['accent','Detail','装饰'],['skin','Face','面部'],['hairColor','Hair','头发']].map(([key,en,zh])=>`<label><input type="color" data-color="${key}" value="${c[key]}" aria-label="${t(en,zh)}"><span>${t(en,zh)}</span></label>`).join('')}</div><details class="props-section"><summary>${t('Props & accessories','道具与配件')}</summary><div class="row wrap">${['fan','letter','lantern','sword','bag'].map((a,i)=>`<button data-add-prop="${a}">${t(['Fan','Letter','Lantern','Sword','Bag'][i],['扇子','信件','灯笼','剑','包'][i])}</button>`).join('')}</div>${accessoryControls()}</details>`;
 return '<section class="panel"><div class="panel-head">'+t('Editing: ','正在编辑：')+scopeLabel()+'</div><div class="panel-body">'+characterPicker()+(selectedPart?btn('clear-part',t('← Edit whole puppet','← 编辑整个皮影'),'wide-button small')+partControls():(step==='shape'?shape:style))+lockControls()+'</div></section>';}
function partControls(){const p=character().parts[selectedPart],meta=PARTS.find(p=>p.id===selectedPart);return '<div class="part-edit-title"><strong>'+t(meta.en,meta.zh)+'</strong>'+btn('sketch',t('Draw','绘制'),'small')+'</div>'+[['width','Body width','部件宽度',.65,1.5,.01],['length','Body length','部件长度',.7,1.3,.01],['angle','Joint angle','关节角度',-150,150,1]].map(([key,en,zh,min,max,inc])=>'<label class="field"><span>'+t(en,zh)+' <output id="value-'+key+'">'+p[key]+(key==='angle'?'°':'×')+'</output></span><input type="range" data-part-prop="'+key+'" min="'+min+'" max="'+max+'" step="'+inc+'" value="'+p[key]+'"></label>').join('')+'<label class="checkbox"><input type="checkbox" id="part-lock" '+(p.locked?'checked':'')+'>'+t('Protect this part from AI','锁定此部件，不允许 AI 修改')+'</label><p class="hint">'+t('These controls change the body part. Switch to Whole puppet → Style for clothing.','这些控件调整身体部件。服装请在“整个皮影 → 装扮”中调整。')+'</p>';}
function accessoryControls(){const c=character();if(!c.accessories.length)return `<p class="hint">${t('Add a prop, then drag it into place.','添加道具后，可以拖动调整位置。')}</p>`;const a=c.accessories.find(a=>a.id===selectedAccessory)||c.accessories.at(-1);selectedAccessory=a.id;return `<div class="divider"></div><label class="field"><span>${t('Selected prop','选中的道具')}</span><select id="prop-select">${c.accessories.map((p,i)=>`<option value="${p.id}" ${p.id===a.id?'selected':''}>${i+1}. ${e(p.type)}</option>`).join('')}</select></label><label class="field"><span>${t('Attached to','连接到')}</span><select data-prop-field="parent">${PARTS.map(p=>`<option value="${p.id}" ${p.id===a.parent?'selected':''}>${t(p.en,p.zh)}</option>`).join('')}</select></label>${[['scale',t('Size','大小'),.4,2,.05],['angle',t('Rotation','旋转'),-180,180,1]].map(([k,label,min,max,s])=>`<label class="field"><span>${label}</span><input type="range" data-prop-field="${k}" min="${min}" max="${max}" step="${s}" value="${a[k]}"></label>`).join('')}${btn('remove-prop',t('Remove prop','删除道具'),'small ghost danger')}`;}
function stagePanel(isMotion=false){const c=character();return '<div class="stage-wrap"><div class="stage-toolbar"><span class="scope-label">'+t('Editing: ','正在编辑：')+scopeLabel()+'</span><div class="segmented">'+['color','shadow'].map(v=>'<button data-view="'+v+'" aria-pressed="'+(v===view)+'" class="'+(v===view?'active':'')+'">'+(v==='color'?t('Color','彩色'):t('Silhouette','剪影'))+'</button>').join('')+'</div>'+btn('joints',t('Joints','关节'),'small', 'aria-pressed="'+showJoints+'"')+'</div><div class="stage '+(view==='shadow'?'shadow':'')+'" id="stage">'+fullSvg(c,{selected:selectedPart,joints:showJoints,angles:isMotion?pose(motion,1):{}})+'</div><div class="stage-bottom"><span>'+e(displayName(c))+'</span><span>'+project.height+' mm · '+t('10 parts','10 个部件')+'</span></div></div><div class="stage-footer"><div class="row">'+btn('undo',icon('undo'),'icon','aria-label="'+t('Undo','撤销')+'" '+(undoStack.length?'':'disabled'))+btn('redo',icon('redo'),'icon','aria-label="'+t('Redo','重做')+'" '+(redoStack.length?'':'disabled'))+'</div>'+btn('parts',t('Inspect parts','检查部件'),'small','aria-expanded="'+showParts+'"')+btn('snapshot',t('Keep version','保存版本'),'small')+'</div>'+(showParts?'<div class="parts-grid">'+PARTS.map(p=>'<button class="part-tile" data-select-part="'+p.id+'">'+partPreview(c,p.id)+'<span>'+t(p.en,p.zh)+'</span></button>').join('')+'</div>':'');}
function assistantPanel(task='design'){
 const stale=proposal&&proposalBase!==JSON.stringify({character:character(),story:project.story});
 const current=character(),candidate=proposal?.design?applyDesign(current,proposal,proposalTarget):null,changes=candidate?designChanges(current,candidate):[],pending=candidate?applySelectedChanges(current,proposal,proposalTarget,changeSelection):null;
 return `<section class="panel assistant-panel"><div class="panel-head"><strong>${t('AI design help','AI 设计助手')}</strong>${btn('toggle-ai',t('Close','关闭'),'small')}</div><p class="scope-banner">${t('Request scope: ','请求范围：')}${scopeLabel()} ${selectedPart?btn('clear-part',t('Whole puppet','整个皮影'),'small'):''}</p><div class="chat-log" aria-live="polite">${chat.length?chat.map((m,i)=>`<div class="chat-msg ${m.role}">${e(m.content)}${m.image?`<img class="chat-image" src="${m.image}" alt="${t('Generated reference image','生成的参考图')}">`+btn('download-image',icon('download')+' '+t('Download image','下载图片'),'small','data-idx="'+i+'"'):''}</div>`).join(''):t('Describe the changes you want. You will review a preview before anything is applied.','描述你想要的修改。应用前可先预览并选择。')}${busy?'<p>'+t('Preparing a proposal…','正在准备方案……')+'</p>':''}</div>${proposal?`<div class="proposal"><h3>${t('Review changes','审核修改')}</h3>${stale?'<p class="notice">'+t('The project has changed. Request a new preview before applying.','项目已修改，请重新预览后再应用。')+'</p>':''}${candidate?`<div class="comparison"><figure><figcaption>${t('Before','修改前')}</figcaption>${fullSvg(current,{instance:'before'})}</figure><figure><figcaption>${t('Proposed','拟议修改')}</figcaption>${fullSvg(pending,{instance:'after'})}</figure></div><div class="change-list">${changes.length?changes.map(ch=>`<label class="checkbox change-item"><input type="checkbox" data-change-path="${ch.path}" ${changeSelection.includes(ch.path)?'checked':''}><span><strong>${changeLabel(ch.path)}</strong><small>${changeValue(ch.before)} → ${changeValue(ch.after)}</small></span></label>`).join(''):'<p>'+t('No editable changes. The request may be unsupported or protected by your locks.','没有可应用的修改。请求可能不受支持，或修改已被锁定。')+'</p>'}</div><p class="hint">${t('Everything not selected stays unchanged. Print height and protected features are preserved.','未勾选的内容保持原样。打印高度及锁定特征保持不变。')}</p>`:''}${proposal.story?`<label class="checkbox"><input id="accept-story" type="checkbox" ${changeSelection.includes('story')?'checked':''}>${t('Use this script','使用此剧本')}</label><div class="script-proposal">${e(proposal.story.script)}</div>`:''}${proposal.characters?`<p>${t('Choose characters to add:','选择要添加的角色：')}</p>${proposal.characters.map((c,i)=>`<label class="checkbox"><input type="checkbox" data-cast-index="${i}" ${castSelection.includes(i)?'checked':''}>${e(displayName(c))}</label>`).join('')}`:''}<div class="row wrap">${btn('apply-proposal',t('Apply selected changes','应用所选修改'),'primary small',!stale&&(changeSelection.length||castSelection.length)?'':'disabled')}${btn('dismiss-proposal',t('Discard','放弃'),'small')}</div></div>`:''}<form id="chat-form" class="chat-entry" data-task="${task}"><label for="chat-input">${t('What would you like to change?','你想修改什么？')}</label><textarea id="chat-input" maxlength="1600" placeholder="${task==='story'?t('Describe your own story idea…','描述你自己的故事想法……'):selectedPart?t('Change this part’s width, length or angle…','调整此部件的宽度、长度或角度……'):t('For example: wider sleeves; keep the face and body.','例如：加宽袖子，保留面部与身体。')}" ${busy?'disabled':''}></textarea>${busy?btn('cancel-ai',t('Cancel','取消'),'small'):'<button type="submit" class="primary">'+t('Preview an AI edit','预览 AI 修改')+'</button>'}<div class="image-actions">${imageBusy?btn('cancel-image',t('Cancel image','取消图像'),'small'):btn('ref-image',icon('spark')+' '+t('Reference image','生成参考图'),'small',busy?'disabled':'')+btn('pattern-image',t('Pattern tile','生成纹样'),'small',busy?'disabled':'')}<p class="hint">${t('Generated images are inspiration only — they never change your editable puppet. Pattern tiles can be printed as decoration references.','生成的图片仅供灵感参考，不会改变可编辑的皮影。纹样可下载打印作为装饰参考。')}</p></div></form><div class="connection">${connectionState==='connected'?t('AI connected','AI 已连接'):t('AI connection not checked','尚未检查 AI 连接')} ${btn('connection',t('Connection details','连接详情'),'small ghost')}</div></section>`;
}
function designPage(){return '<div class="workspace design-workspace"><aside class="left-column">'+designControls()+'</aside><div class="center-column">'+stagePanel()+'<div class="ai-launch">'+btn('toggle-ai',icon('spark')+' '+(aiOpen?t('Hide AI help','收起 AI 助手'):t('Ask AI to help','请 AI 协助')),'small','aria-expanded="'+aiOpen+'"')+'<p class="hint">'+t('Manual controls work without AI.','手动控件无需 AI 即可使用。')+'</p></div>'+(aiOpen?assistantPanel():'')+'</div></div>';}
function storyPage(){return '<div class="wide-grid"><section class="panel"><div class="panel-head">'+t('Project story','项目故事')+'<span class="tag">'+t('Optional','可选')+'</span></div><div class="panel-body">'+field(t('Project title','项目标题'),'project.title',project.title)+field(t('Time & place','时间与地点'),'story.setting',project.story.setting)+field(t('Your idea or central problem','你的想法或核心问题'),'story.theme',project.story.theme)+'<label class="field"><span>'+t('Performance length (minutes)','表演时长（分钟）')+'</span><input type="number" data-number="duration" min="1" max="10" value="'+project.story.duration+'"></label>'+field(t('Write or paste your script','编写或粘贴剧本'),'story.script',project.story.script,{kind:'textarea',rows:12})+'<div class="row wrap">'+btn('draft-story',t('Draft from my idea','根据我的想法起草'),'primary small',busy?'disabled':'')+btn('extract-characters',t('Suggest characters from script','从剧本提取角色'),'small',busy||!project.story.script.trim()?'disabled':'')+'</div><p class="hint">'+t('AI characters are suggestions. Select each one before adding it to your project.','AI 提取的角色仅供建议。逐个选择后才会添加到项目。')+'</p></div></section><aside>'+(aiOpen?assistantPanel('story'):btn('toggle-ai',t('Open story assistant','打开故事助手'),'wide-button'))+'</aside></div>';}
function charactersPage(){return '<div class="character-cards">'+project.characters.map((c,i)=>'<article class="character-card '+(i===project.selected?'active':'')+'">'+fullSvg(c,{instance:'card-'+i})+'<div><h3>'+e(displayName(c))+'</h3><p>'+e(c.role)+'</p><div class="row">'+btn('choose-character',t('Edit puppet','编辑皮影'),'primary small','data-index="'+i+'"')+btn('delete-character',t('Remove','移除'),'small','data-index="'+i+'" '+(project.characters.length===1?'disabled':''))+'</div></div></article>').join('')+'</div><div class="add-template"><button data-template="neutral" class="primary">'+icon('plus')+t('Add a blank puppet','添加空白皮影')+'</button><p class="hint">'+t('A basic connected template with no name, role, costume or story assigned.','由相连部件组成的基础模板，名称、角色、服装和故事均由你决定。')+'</p></div>';}
function motionPage(){return `<div class="workspace motion-workspace"><aside class="left-column"><section class="panel"><div class="panel-head">${t('Rehearsal','动作排练')}</div><div class="panel-body">${characterPicker()}${selectedPart?btn('clear-part',t('Edit whole puppet','编辑整个皮影'),'small'):''}${field(t('Our required action','需要完成的动作'),'action',character().action,{kind:'textarea'})}<div class="controls-list">${[['wave','Wave hello','挥手问好'],['walk','Walk','行走'],['read','Read a letter','读信'],['custom','My joint angles','自定角度']].map(([id,en,zh])=>`<button data-motion="${id}" class="${motion===id?'active':''}">${t(en,zh)} ${icon('arrow')}</button>`).join('')}</div><div class="divider"></div>${selectedPart?partControls():`<p class="hint">${t('Select a body part to adjust its angle. Choose “My joint angles” to see your own pose.','选择部件调整角度，点击“自定角度”查看自己的姿态。')}</p>`}${btn('reset-pose',t('Reset all joint angles','重置所有关节角度'),'small wide-button')}</div></section></aside><div class="center-column">${stagePanel(true)}<div class="motion-controls">${btn('play',(playing?icon('pause'):icon('play'))+' '+(playing?t('Pause','暂停'):t('Play motion','播放动作')),'dark',motion==='custom'?'disabled':'')}${btn('keep-pose',t('Use this pose','使用此姿态'),'small')}</div><p class="hint">${t('Animation checks arrangement and rotation only. It does not simulate material stiffness, gravity, rod control, or collisions.','动画仅预览结构与旋转，不模拟材料刚度、重力、操纵杆控制或碰撞。')}</p></div><aside class="right-column"><section class="panel"><div class="panel-head">${t('Test, notice, revise','测试、观察、改进')}</div><div class="panel-body"><ol class="instruction-list"><li>${t('Can the audience read the gesture?','观众能看懂这个动作吗？')}</li><li>${t('Do the pieces overlap at every joint?','各关节处的部件是否保持重叠？')}</li><li>${t('Does the prop stay with the correct hand?','道具是否跟随正确的手？')}</li><li>${t('Can you reproduce this with control rods?','能否用操纵杆完成这个动作？')}</li></ol>${field(t('What did you discover?','你发现了什么？'),'reflection',character().reflection,{kind:'textarea',rows:6})}${btn('snapshot',t('Save my observations','保存观察记录'),'primary small')}</div></section><div class="note-card"><h3>${t('Make the connection visible','让学科联系清晰可见')}</h3><p>${t('A joint is a pivot. Changing its position or the length of a limb changes the path of the hand. What does your story need the hand to reach?','关节是一个转动支点。关节的位置和肢体长度会影响手的运动轨迹。故事中的手需要够到哪里？')}</p></div></aside></div>`;}
function makePage(){const c=character(),check=inspection(c,project.height,project.hole);return `<div class="wide-grid"><div><section class="panel"><div class="panel-head">${t('Printable body parts','可打印身体部件')}<span class="tag">A4 · ${check.pages} ${t('pages','页')}</span></div><div class="print-preview">${printPages(c,project.height,project.hole).join('')}</div></section><div class="summary-grid" style="margin-top:15px"><div><strong>${check.parts}</strong><small>${t('separate pieces','独立部件')}</small></div><div><strong>${check.connections}</strong><small>${t('joint connections','关节连接')}</small></div><div><strong>${project.height}<small> mm</small></strong><small>${t('neutral bounding height','自然姿态外框高度')}</small></div></div></div><aside><section class="panel"><div class="panel-head">${t('Prepare to make','制作准备')}</div><div class="panel-body">${characterPicker()}<div class="two-cols"><label class="field"><span>${t('Finished print height (mm)','高度（毫米）')}</span><input type="number" data-number="height" min="180" max="350" value="${project.height}"></label><label class="field"><span>${t('Hole diameter (mm)','关节孔径（毫米）')}</span><input type="number" data-number="hole" min="1.5" max="4" step=".5" value="${project.hole}"></label></div><div class="notice">${t('Prototype templates: choose material and fasteners with your teacher. Print one joint first to check the hole, overlap and strength. Decorative lines are printed artwork, not cut-outs.','原型模板：与老师一起选择材料和连接件。先打印一个关节，检查孔径、重叠和强度。装饰线是印刷图案，不是镂空切割线。')}</div>${check.minMargin<2.5?`<p class="danger hint">${t('Some narrow joints have little material around the hole. Increase part width or reduce hole diameter.','部分关节孔周围材料较少，请增加部件宽度或减小孔径。')}</p>${btn('fix-joint',t('Adjust narrowest joint','调整最窄关节'),'small')}`:''}${!check.printable?'<p class="notice">'+t('A part exceeds A4. Set print height to '+check.maxHeight+' mm or less, or shorten the garment.','某部件超出 A4。请将打印高度调至 '+check.maxHeight+' 毫米或更低，或缩短服装。')+'</p>':''}<div class="export-list">${btn('print',icon('make')+' '+t('Print / save PDF','打印 / 保存 PDF')+`<small>${t('Body pieces + assembly guide · Actual size','身体部件和组装指南 · 按实际大小')}</small>`,'primary')}<details><summary>${t('More exports','更多导出')}</summary>${btn('export-svg',icon('download')+' '+t('Character SVG','角色 SVG')+`<small>${t('Complete editable vector image','完整矢量图像')}</small>`)}${btn('export-png',icon('download')+' '+t('Character PNG','角色 PNG')+`<small>${t('Transparent image, 1600 × 1240','透明图像，1600 × 1240')}</small>`)}${btn('export-parts',icon('download')+' '+t('Parts sheets (SVG)','部件模板（SVG）'))}${check.accessories?btn('export-props',icon('download')+' '+t('Separate props sheet','单独的道具模板')):''}${btn('save',icon('save')+' '+t('Editable project (.json)','可编辑项目（.json）'))}</details></div><div class="divider"></div><ol class="instruction-list"><li>${t('Print at 100%. Check the 50 mm reference.','按 100% 打印，核对 50 毫米标尺。')}</li><li>${t('Cut the outside contour of each piece.','沿每个部件的外轮廓剪裁。')}</li><li>${t('Match joint marks using the assembly guide.','根据组装指南对齐关节标记。')}</li><li>${t('Fasten loosely enough to turn; test rods and lighting.','连接后应能自由转动；测试操纵杆和光照。')}</li></ol></div></section></aside></div>`;}
function historyPage(){return `<div class="wide-grid"><section class="panel"><div class="panel-head">${t('Saved design versions','已保存的设计版本')}${btn('snapshot',icon('plus')+' '+t('Save current','保存当前'),'small')}</div><div class="panel-body">${project.revisions.length?project.revisions.slice().reverse().map(r=>`<div class="history-item"><div class="row"><strong>${e(displayName(r.character))}</strong><small>${e(new Date(r.date).toLocaleString(project.language==='zh'?'zh-CN':'en-GB'))}</small></div><p>${e(r.note)}</p><div class="row">${btn('restore-version',t('Restore version','恢复版本'),'small',`data-id="${r.id}"`)}</div></div>`).join(''):`<div class="empty">${t('No saved versions yet. Keep a version when you make a meaningful design decision.','尚无版本记录。在做出重要设计决定时，保存一个版本。')}</div>`}</div></section><section class="panel"><div class="panel-head">${t('My design reasoning','我的设计思考')}</div><div class="panel-body">${field(t('Why did you make these choices? What did you test?','你为什么做出这些选择？测试了什么？'),'reflection',character().reflection,{kind:'textarea',rows:8})}${btn('snapshot',t('Save a version with this note','保存版本及说明'),'primary small')}<p class="hint">${t('The latest 12 saved versions are included in the project file. Download it to move between devices.','项目文件保存最近 12 个版本。下载后可在其他设备打开。')}</p></div></section></div>`;}
function updateStage(){const c=character(),svg=$('#stage>svg');if(svg)svg.innerHTML=`<g transform="translate(395 176)">${puppet(c,{selected:selectedPart,joints:showJoints,angles:step==='motion'?pose(motion,1):{}})}</g>`;}
function animate(time=0){if(!playing)return;const svg=$('#stage>svg');if(svg)svg.innerHTML=`<g transform="translate(395 176)">${puppet(character(),{selected:selectedPart,joints:showJoints,angles:pose(motion,time/1000)})}</g>`;frame=requestAnimationFrame(animate);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const safeName=()=>character().name.replace(/[^\p{L}\p{N}_-]+/gu,'_').slice(0,50)||'puppet';
function snapshot(note){project.revisions.push({id:uid(),date:new Date().toISOString(),note:note||character().reflection||t('Design checkpoint','设计检查点'),character:clone(character())});project.revisions=project.revisions.slice(-12);}
function assemblyHtml(){const c=character();return `<section class="print-page assembly-page"><h1>${e(displayName(c))} · Assembly / 组装</h1><p>${e(c.action)}</p><ol><li>Print at 100% / 按实际大小打印。Check the 50 mm scale / 核对 50 毫米标尺。</li><li>Cut the outer contour / 沿外轮廓剪裁。Pattern lines are printed decoration / 纹样线为印刷装饰。</li><li>Align the marked circles / 对齐关节孔。Put the far limbs behind the torso / 后侧肢体放在躯干后方。</li><li>Test suitable fasteners and control rods with your teacher / 与老师测试合适的连接件和操纵杆。Do not tighten joints until they cannot turn / 避免关节过紧。</li></ol><table style="width:100%;font-size:11px;border-collapse:collapse">${PARTS.filter(p=>p.parent).map(p=>`<tr><td style="padding:6px;border-bottom:1px solid #ddd">${e(p.en)} / ${e(p.zh)}</td><td>→ ${e(PARTS.find(x=>x.id===p.parent).en)} / ${e(PARTS.find(x=>x.id===p.parent).zh)}</td></tr>`).join('')}</table><p>Accessories are separate props. Check their size and choose removable attachments after testing. / 道具单独制作，测试后确定尺寸和可拆卸连接方式。</p><p>Record one successful action and one change to make. / 记录一个成功动作和一项需要改进的地方。</p>${fullSvg(c,{joints:true,instance:'guide'}).replace('width="800" height="620"','width="280" height="217"')}</section>`;}
function checkPrint(){const check=inspection(character(),project.height,project.hole);if(check.printable)return true;toast(t('A part is too large for A4. Reduce print height to '+check.maxHeight+' mm or shorten the garment.','某个部件超出 A4 页面。请将打印高度减至 '+check.maxHeight+' 毫米，或缩短服装。'));return false;}

function showDialog(title,body,actions=''){const div=document.createElement('div');div.className='dialog-backdrop';div.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-label="${e(title)}"><h2>${e(title)}</h2>${body}<div class="row">${actions}${btn('close-dialog',t('Close','关闭'),'small')}</div></section>`;document.body.append(div);div.querySelector('button')?.focus();div.addEventListener('click',event=>{if(event.target===div)div.remove();});}
async function ai(task,question){if(busy)return;aiOpen=true;proposal=null;changeSelection=[];castSelection=[];busy=true;proposalBase=JSON.stringify({character:character(),story:project.story});proposalTarget=selectedPart;chat.push({role:'user',content:question});controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),60000);render();try{const result=await askAssistant({task,question,language:project.language,character:clone(character()),story:clone(project.story),selectedPart:task==='design'?selectedPart:null,history:chat.slice(0,-1)},{signal:controller.signal,endpoint});connectionState='connected';chat.push({role:'assistant',content:result.reply});if(proposalBase!==JSON.stringify({character:character(),story:project.story})){chat.push({role:'assistant',content:t('The project changed while AI was working. Please request a new preview.','AI 工作期间项目已修改，请重新请求预览。')});}else if(result.design||result.story||result.characters){proposal=result;if(result.design)changeSelection=designChanges(character(),applyDesign(character(),result,proposalTarget)).map(x=>x.path);if(result.story)changeSelection.push('story');castSelection=[];}}catch(error){chat.push({role:'assistant',content:error.name==='AbortError'?t('Request stopped or timed out. Your design has not changed.','请求已停止或超时，设计未改变。'):error.message});}finally{clearTimeout(timeout);busy=false;controller=null;render();}}
async function makeImage(kind){
 if(busy||imageBusy)return;
 const input=$('#chat-input'),extra=input?input.value.trim():'',c=character();
 if(kind==='pattern'&&!extra){toast(t('Describe the motif in the request box first — for example “peonies and clouds”.','请先在输入框描述纹样主题，例如“牡丹与祥云”。'));return;}
 const prompt=(extra||[c.name,c.role,c.brief,c.action,'clothing: '+c.clothing,'pattern: '+c.pattern,'hair: '+c.hair,'colors: '+c.primary+', '+c.secondary+', '+c.accent].filter(Boolean).join(', ')).slice(0,800);
 aiOpen=true;imageBusy=true;imageController=new AbortController();
 chat.push({role:'user',content:extra||t('Generate a reference image of my current puppet.','为当前皮影生成一张参考图。')});render();
 try{
  const r=await generateStudioImage({kind,prompt},{signal:imageController.signal,endpoint});
  connectionState='connected';
  chat.push({role:'assistant',kind,content:kind==='pattern'?t('Generated pattern tile — download and print it as a decoration reference. It is not part of the vector design.','生成的纹样——可下载打印作为装饰参考，不属于矢量设计。'):t('Generated reference — inspiration only; your editable puppet is unchanged.','生成的参考图——仅供灵感，可编辑的皮影未改变。'),image:r.dataUrl});
 }catch(error){
  chat.push({role:'assistant',content:error.name==='AbortError'?t('Image request stopped.','图像请求已停止。'):error.message});
 }finally{imageBusy=false;imageController=null;render();}
}
root.addEventListener('submit',event=>{if(event.target.id==='chat-form'){event.preventDefault();const input=$('#chat-input');if(input.value.trim())ai(event.target.dataset.task,input.value.trim());}});
root.addEventListener('click',async event=>{
 const target=event.target.closest('button');if(!target)return;
 if(target.dataset.choice){commit(()=>{character()[target.dataset.choice]=target.dataset.value;});return;}
 if(target.dataset.step){step=target.dataset.step;selectedPart=null;render();return;}
 if(target.dataset.selectPart){selectedPart=target.dataset.selectPart;render();return;}
 if(target.dataset.palette){commit(()=>{[character().primary,character().secondary,character().accent]=PALETTES[target.dataset.palette];});return;}
 if(target.dataset.view){view=target.dataset.view;render();return;}
 if(target.dataset.prompt){$('#chat-input').value=target.dataset.prompt;$('#chat-input').focus();return;}
 if(target.dataset.template){if(project.characters.length>=12)return toast(t('Maximum 12 characters per project.','每个项目最多 12 个角色。'));commit(()=>{project.characters.push(createCharacter(target.dataset.template));project.selected=project.characters.length-1;selectedPart=null;step='shape';chat=[];proposal=null;});return;}
 if(target.dataset.addProp){if(character().accessories.length>=8)return toast(t('Maximum 8 props per character.','每个角色最多 8 个道具。'));commit(()=>{const a={id:uid(),type:target.dataset.addProp,parent:'forearmFront',x:22,y:79,scale:1,angle:0,color:character().accent};character().accessories.push(a);selectedAccessory=a.id;});return;}
 if(target.dataset.motion){motion=target.dataset.motion;if(motion==='custom')playing=false;render();return;}
 switch(target.dataset.action){
 case 'fix-joint':{const smallest=PARTS.filter(p=>p.id!=='torso'&&p.id!=='head').sort((a,b)=>character().parts[a.id].width-character().parts[b.id].width)[0];selectedPart=smallest.id;step='shape';render();break;}
 case 'toggle-ai':aiOpen=!aiOpen;render();break;
 case 'parts':showParts=!showParts;render();break;
 case 'versions':versionsOpen=!versionsOpen;render();break;
 case 'new-project':showDialog(t('Start a blank project?','开始空白项目？'),'<p>'+t('Your current project stays recoverable with Undo. Download it first if you need a separate file.','当前项目可通过撤销恢复。如需单独备份，请先下载项目。')+'</p>',btn('confirm-new',t('Start blank project','开始空白项目'),'primary'));break;
 case 'language':project.language=project.language==='en'?'zh':'en';document.documentElement.lang=project.language;changed();render();break;
 case 'save':downloadProject();toast(t('Project downloaded. Open this file to continue after closing.','项目已下载。关闭后请打开此文件继续创作。'));break;
 case 'import':$('#file-input').click();break;
 case 'undo':if(undoStack.length){redoStack.push(JSON.stringify(project));project=JSON.parse(undoStack.pop());changed();render();}break;
 case 'redo':if(redoStack.length){undoStack.push(JSON.stringify(project));project=JSON.parse(redoStack.pop());changed();render();}break;
 case 'clear-part':selectedPart=null;render();break;
 case 'joints':showJoints=!showJoints;render();break;
 case 'snapshot':commit(()=>snapshot());toast(t('Version saved with your observations.','已保存版本及观察记录。'));break;
 case 'choose-character':project.selected=Number(target.dataset.index);selectedPart=null;chat=[];proposal=null;step='shape';changed();render();break;
 case 'delete-character':if(project.characters.length>1){const i=Number(target.dataset.index);showDialog(t('Remove this character?','删除这个角色？'),`<p>${e(project.characters[i].name)}</p>`,btn('confirm-delete',t('Remove','删除'),'primary small',`data-index="${i}"`));}break;
 case 'to-characters':step='characters';render();break;
 case 'remove-prop':commit(()=>{character().accessories=character().accessories.filter(a=>a.id!==selectedAccessory);selectedAccessory=null;});break;
 case 'draft-story':if(![project.story.theme,project.story.setting,project.story.script].some(v=>v.trim())){toast(t('Add your idea, setting or script first.','请先填写想法、背景或剧本。'));break;}ai('story',t('Draft a continuous puppet play using our setting, theme, duration and current cast. Include dialogue and short performable movement cues.','根据我们的背景、主题、时长和角色起草连续皮影剧本，包含对白和简短可表演的动作提示。'));break;
 case 'extract-characters':ai('extract',t('Extract the characters from our script, with visible appearance and one required action for each.','从剧本提取角色，为每个角色提供可见外观特征和一个需要完成的动作。'));break;
 case 'cancel-ai':controller?.abort();break;
 case 'ref-image':makeImage('reference');break;
 case 'pattern-image':makeImage('pattern');break;
 case 'cancel-image':imageController?.abort();break;
 case 'download-image':{const m=chat[Number(target.dataset.idx)];if(m?.image){const a=document.createElement('a');a.href=m.image;a.download=safeName()+(m.kind==='pattern'?'-pattern':'-reference')+'.png';a.click();}break;}
 case 'dismiss-proposal':proposal=null;render();break;
 case 'apply-proposal':if(proposal){if(proposalBase!==JSON.stringify({character:character(),story:project.story})){toast(t('Your project changed since this proposal. Ask again using the current design.','角色已更改，请基于当前设计重新请求。'));break;}commit(()=>{snapshot(t('Before AI proposal','应用 AI 方案前'));if(proposal.design)project.characters[project.selected]=applySelectedChanges(character(),proposal,proposalTarget,changeSelection);if(proposal.story&&changeSelection.includes('story')){project.story.script=proposal.story.script;if(proposal.story.title)project.title=proposal.story.title;}if(proposal.characters){for(const [index,c] of proposal.characters.entries()){if(!castSelection.includes(index))continue;if(project.characters.length>=12)break;const existing=project.characters.find(p=>p.name===c.name);if(!existing)project.characters.push(c);}}proposal=null;});toast(t('Proposal applied. You can undo it.','已应用方案，可撤销。'));}break;
 case 'play':playing=!playing;render();break;
 case 'keep-pose':commit(()=>{for(const [k,v]of Object.entries(pose(motion,1)))character().parts[k].angle=v;motion='custom';playing=false;});break;
 case 'reset-pose':commit(()=>{for(const p of Object.values(character().parts))p.angle=0;motion='custom';playing=false;});break;
 case 'export-svg':download(safeName()+'.svg',fullSvg(character()),'image/svg+xml');break;
 case 'export-parts':{if(!checkPrint())break;const pages=printPages(character(),project.height,project.hole);showDialog(t('Download parts sheets','下载部件模板'),`<p>${t('Download each A4 page, then print at actual size.','下载每张 A4 页面，再按实际大小打印。')}</p><div class="export-list">${pages.map((_,i)=>btn('download-sheet',t('Sheet ','第 ')+(i+1)+(project.language==='zh'?' 页':''),'small',`data-index="${i}"`)).join('')}</div>`);break;}
 case 'export-props':showDialog(t('Props sheets','道具打印页'),'<div class="export-list">'+propPrintPages(character(),project.height).map((_,i)=>btn('download-prop-sheet',t('Sheet ','第 ')+(i+1),'small','data-index="'+i+'"')).join('')+'</div>');break;
 case 'print':if(!checkPrint())break;$('#print-root').innerHTML=printPages(character(),project.height,project.hole).map(s=>`<div class="print-page">${s}</div>`).join('')+propPrintPages(character(),project.height).map(s=>'<div class="print-page">'+s+'</div>').join('')+assemblyHtml();window.print();break;
 case 'export-png':{const svg=fullSvg(character()),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1240;canvas.getContext('2d').drawImage(image,0,0,1600,1240);canvas.toBlob(blob=>{if(blob)download(safeName()+'.png',blob,'image/png');URL.revokeObjectURL(url);});};image.onerror=()=>{URL.revokeObjectURL(url);toast(t('PNG export failed. Try SVG.','PNG 导出失败，请尝试 SVG。'));};image.src=url;break;}
 case 'restore-version':{const r=project.revisions.find(r=>r.id===target.dataset.id);if(r)commit(()=>{const index=project.characters.findIndex(c=>c.id===r.character.id);if(index>=0){project.characters[index]=clone(r.character);project.selected=index;}else if(project.characters.length<12){project.characters.push(clone(r.character));project.selected=project.characters.length-1;}selectedPart=null;step='shape';versionsOpen=false;});break;}
 case 'sketch':openSketch();break;
 case 'connection':showDialog(t('Protected AI connection','受保护的 AI 连接'),`<p>${t('This studio uses your protected Kimi puppet relay. Requests contain your prompt, current character and story. No API key is stored in the browser or project file.','本工作室复用六轴机器人配置的 Kimi 托管接口。请求包括提示词、当前角色和故事。浏览器及项目文件均不存储 API 密钥。')}</p><p><code>${e(endpoint)}</code></p><p>${t('If the relay rejects a request, its maintainer may need to update the allowed origin or supported puppet instructions. Manual design, saving and printing remain available.','如果接口拒绝此来源或固定使用机器人指令，需由维护者部署项目提供的皮影专用接口。手动设计、保存和打印仍可使用。')}</p>`,btn('test-ai',t('Test connection','测试连接'),'primary small'));break;
 case 'about':showDialog(t('A workshop for new stories','新故事的创作工坊'),`<p>${t('Inspired by ShadowMaker (Yao et al., CHI EA 2024), this independent prototype starts with connected parts and keeps student design decisions editable. It does not reproduce the research implementation or its trained models.','受 ShadowMaker（Yao 等，CHI EA 2024）启发，本独立原型从可连接部件开始，让学生的设计保持可编辑。它未复制论文实现或训练模型。')}</p><p>${t('The studio uses vector templates and AI design proposals, with optional AI reference images for inspiration. Generated images never become puppet parts, and uploaded photos are not automatically separated. Projects stay in this session only. Download JSON to keep or share them; reopen starts fresh.','工作室使用矢量模板与 AI 设计建议，并可生成仅供灵感的参考图。生成的图像不会成为皮影部件，上传的照片也不会被自动拆分。项目仅保留在本次会话中，请下载 JSON 以保留或分享；再次打开时将重新开始。')}</p>`);break;
 }
});
document.addEventListener('click',event=>{const b=event.target.closest('button[data-action]');if(!b||root.contains(b))return;if(b.dataset.action==='confirm-new'){commit(()=>{const lang=project.language;project=createProject();project.language=lang;step='shape';selectedPart=null;proposal=null;chat=[];aiOpen=false;showParts=false;});b.closest('.dialog-backdrop')?.remove();}if(b.dataset.action==='close-dialog')b.closest('.dialog-backdrop')?.remove();if(b.dataset.action==='confirm-delete'){const i=Number(b.dataset.index);commit(()=>{project.characters.splice(i,1);project.selected=Math.min(project.selected,project.characters.length-1);proposal=null;chat=[];});b.closest('.dialog-backdrop')?.remove();}if(b.dataset.action==='download-prop-sheet')download(safeName()+'-props-'+(Number(b.dataset.index)+1)+'.svg',propPrintPages(character(),project.height)[Number(b.dataset.index)],'image/svg+xml');if(b.dataset.action==='download-sheet')download(safeName()+'-parts-'+(Number(b.dataset.index)+1)+'.svg',printPages(character(),project.height,project.hole)[Number(b.dataset.index)],'image/svg+xml');if(b.dataset.action==='test-ai'){b.closest('.dialog-backdrop')?.remove();ai('discuss',t('Connection check. Briefly confirm that you are the shadow-puppet design assistant. Do not propose changes.','连接测试。简短确认你是皮影设计助手，不要提出修改。'));}if(b.dataset.action==='clear-sketch'){commit(()=>{character().parts[selectedPart].strokes=[];});b.closest('.dialog-backdrop')?.remove();openSketch();}});
let sliderCheckpoint=false;
root.addEventListener('pointerdown',event=>{if(event.target.matches('input[type=range],input[type=color]')){checkpoint();sliderCheckpoint=true;}});
root.addEventListener('input',event=>{const el=event.target,c=character();if(el.dataset.garment){if(!sliderCheckpoint){checkpoint();sliderCheckpoint=true;}c.garment[el.dataset.garment]=Number(el.value);const out=$('#garment-'+el.dataset.garment);if(out)out.textContent=el.value+'×';changed();updateStage();}if(el.dataset.partProp){if(!sliderCheckpoint){checkpoint();sliderCheckpoint=true;}c.parts[selectedPart][el.dataset.partProp]=Number(el.value);const out=$('#value-'+el.dataset.partProp);if(out)out.textContent=el.value+(el.dataset.partProp==='angle'?'°':'×');if(step==='motion'){motion='custom';playing=false;}changed();updateStage();}if(el.dataset.color){c[el.dataset.color]=el.value;changed();updateStage();}if(el.dataset.propField&&el.type==='range'){const a=c.accessories.find(a=>a.id===selectedAccessory);if(a){a[el.dataset.propField]=Number(el.value);changed();updateStage();}}});
root.addEventListener('change',event=>{const el=event.target,c=character();if(el.dataset.changePath){changeSelection=el.checked?[...changeSelection,el.dataset.changePath]:changeSelection.filter(k=>k!==el.dataset.changePath);render();return;}if(el.id==='accept-story'){changeSelection=el.checked?[...changeSelection,'story']:changeSelection.filter(k=>k!=='story');render();return;}if(el.dataset.castIndex!==undefined){const i=Number(el.dataset.castIndex);castSelection=el.checked?[...castSelection,i]:castSelection.filter(k=>k!==i);render();return;}if(el.dataset.featureLock){commit(()=>{c.locks[el.dataset.featureLock]=el.checked;});return;}if(el.dataset.field){checkpoint();const key=el.dataset.field;if(key.startsWith('project.'))project[key.slice(8)]=el.value;else if(key.startsWith('story.'))project.story[key.slice(6)]=el.value;else c[key]=el.value;changed();if(el.tagName==='SELECT')render();else {updateStage();const extract=$('[data-action="extract-characters"]');if(extract)extract.disabled=busy||!project.story.script.trim();const label=$('.stage-bottom>span');if(label)label.textContent=displayName(c);const option=$('#character-select option:checked');if(option)option.textContent=displayName(c);}}if(el.dataset.number){checkpoint();const k=el.dataset.number,range=k==='height'?[180,350]:k==='hole'?[1.5,4]:[1,10],v=Math.min(range[1],Math.max(range[0],Number(el.value)||range[0]));if(k==='duration')project.story.duration=v;else project[k]=v;changed();render();}if(el.id==='character-select'){project.selected=Number(el.value);selectedPart=null;chat=[];proposal=null;changed();render();}if(el.id==='prop-select'){selectedAccessory=el.value;render();}if(el.id==='part-lock')commit(()=>{c.parts[selectedPart].locked=el.checked;});if(el.dataset.propField&&el.tagName==='SELECT')commit(()=>{const a=c.accessories.find(a=>a.id===selectedAccessory);if(a)a.parent=el.value;});if(el.matches('input[type=range],input[type=color]')){sliderCheckpoint=false;render();}});
$('#file-input').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error(t('Project file is too large (2 MB maximum).','项目文件过大（最大 2 MB）。'));const imported=normalizeProject(JSON.parse(await file.text()));checkpoint();project=imported;proposal=null;chat=[];selectedPart=null;step='shape';changed();render();toast(t('Project opened.','项目已打开。'));}catch(error){toast(error.message);}event.target.value='';});
function bindStage(){const stage=$('#stage');if(!stage)return;let drag=null;stage.addEventListener('pointerdown',event=>{const a=event.target.closest('[data-accessory]');if(!a||playing)return;const item=character().accessories.find(x=>x.id===a.dataset.accessory);if(!item)return;checkpoint();selectedAccessory=item.id;const tx=transforms(character())[item.parent];drag={id:item.id,start:pointer(event),x:item.x,y:item.y,angle:tx.a};stage.setPointerCapture(event.pointerId);event.preventDefault();});stage.addEventListener('pointermove',event=>{if(!drag)return;const p=pointer(event),dx=p.x-drag.start.x,dy=p.y-drag.start.y,a=character().accessories.find(x=>x.id===drag.id);a.x=Math.max(-180,Math.min(180,drag.x+dx*Math.cos(drag.angle)+dy*Math.sin(drag.angle)));a.y=Math.max(-180,Math.min(220,drag.y-dx*Math.sin(drag.angle)+dy*Math.cos(drag.angle)));updateStage();});const stop=()=>{if(drag){drag=null;changed();render();}};stage.addEventListener('pointerup',stop);stage.addEventListener('pointercancel',stop);stage.addEventListener('click',event=>{if(event.target.closest('[data-accessory]'))return;const part=event.target.closest('[data-part]');if(part){selectedPart=part.dataset.part;render();}});stage.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)&&event.target.dataset.part){event.preventDefault();selectedPart=event.target.dataset.part;render();}});}
function pointer(event){const svg=$('#stage>svg'),pt=svg.createSVGPoint();pt.x=event.clientX;pt.y=event.clientY;return pt.matrixTransform(svg.getScreenCTM().inverse());}
function openSketch(){if(!selectedPart)return;const id=selectedPart,c=character(),b=partBounds(c,id);showDialog(t('Draw on this part','在部件上绘制'),`<p>${t('Draw a decoration with your mouse or finger. Your marks remain clipped to the part.','用鼠标或手指绘制装饰，笔迹会限制在部件轮廓内。')}</p><div class="sketch-pad">${partPreview(c,id)}</div>`,btn('clear-sketch',t('Clear drawing','清除绘画'),'small'));const svg=$('.sketch-pad svg');let stroke=null;const point=event=>{const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;const local=p.matrixTransform(svg.getScreenCTM().inverse());return [local.x/c.parts[id].width,local.y/c.parts[id].length];};svg.addEventListener('pointerdown',event=>{if(c.parts[id].strokes.length>=40)return toast(t('Drawing limit reached. Clear some strokes first.','已达到笔画上限，请先清除。'));checkpoint();stroke={color:c.accent,points:[point(event)]};c.parts[id].strokes.push(stroke);svg.setPointerCapture(event.pointerId);event.preventDefault();});svg.addEventListener('pointermove',event=>{if(!stroke)return;if(stroke.points.length<250)stroke.points.push(point(event));svg.innerHTML=new DOMParser().parseFromString(partPreview(c,id),'image/svg+xml').documentElement.innerHTML;});const end=()=>{if(stroke){if(stroke.points.length<2)c.parts[id].strokes.pop();stroke=null;changed();updateStage();}};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);}
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(versionsOpen){versionsOpen=false;render();}else $('.dialog-backdrop')?.remove();}if(event.key==='Tab'&&($('.dialog-backdrop')||versionsOpen)){const items=[...($('.dialog')||$('.versions-drawer')).querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);if(event.shiftKey&&document.activeElement===items[0]){event.preventDefault();items.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===items.at(-1)){event.preventDefault();items[0]?.focus();}}if((event.ctrlKey||event.metaKey)&&event.key==='s'){event.preventDefault();downloadProject();}});
window.addEventListener('pagehide',()=>{controller?.abort();imageController?.abort();cancelAnimationFrame(frame);});
window.addEventListener('pageshow',event=>{if(event.persisted)window.location.reload();});
document.documentElement.lang=project.language;render();
fetch('/api/status').then(r=>r.ok?r.json():null).then(s=>{if(s?.configured||s?.relay)endpoint='/api/puppet';}).catch(()=>{});
